from pathlib import Path
import os,hashlib,json,base64,subprocess
app=Path('/opt/edgepulse/app');backup=Path('/opt/edgepulse/backups/paper-growth-strategy-20261118-121010')
b=json.loads((backup/'manifest.json').read_text());payload={'src/polybot2other/paper_growth.py': '', 'src/polybot2other/static/index.html': '', 'src/polybot2other/static/app.js': '', 'src/polybot2other/static/paper-growth.js': '', 'src/polybot2other/static/paper-growth.css': ''};expected={'src/polybot2other/paper_growth.py': '657240619aaae21328aac33781af99166e594cb29afd48716474f811e21b0e4a', 'src/polybot2other/static/index.html': '8c7750e7f4440b6fe17a9d65d14e0c13935eeb81e700f32663b9ab6b7aff61db', 'src/polybot2other/static/app.js': '0e893a1568b350f4f06850092df3357700bf7eb462530ff5e0ec6d567a7a8dba', 'src/polybot2other/static/paper-growth.js': '11255aba0530d7de13644751a575d2b0abf90e2bf2e2740b118ff047d19a6159', 'src/polybot2other/static/paper-growth.css': '73c8959e5882432e0f71002959420b6a6c769e7990e8e8ee17319d3efc8e28cb'}
for f in payload:assert hashlib.sha256((app/f).read_bytes()).hexdigest()==b['source_hashes'][f], 'source drift: '+f
for f,encoded in payload.items():
 content=base64.b64decode(encoded);assert hashlib.sha256(content).hexdigest()==expected[f]
 path=app/f;temp=path.with_name(path.name+'.strategy-tmp');temp.write_bytes(content);temp.chmod(0o644);os.replace(temp,path)
for f,h in b['source_hashes'].items():
 if f not in payload:assert hashlib.sha256((app/f).read_bytes()).hexdigest()==h, 'unrelated source changed: '+f
(backup/'deployed-files.json').write_text(json.dumps(expected,indent=2))
p=backup/'Dockerfile.growth'
p.write_text('FROM '+b['rollback_image']+'\n'+''.join('COPY '+f+' /app/'+f+'\n' for f in payload))
r=subprocess.run(['docker','build','-f',str(p),'-t','edgepulse:paper',str(app)],capture_output=True,text=True)
(backup/'build.log').write_text(r.stdout+r.stderr)
assert r.returncode==0,(r.stdout+r.stderr)[-2000:]
probe='import importlib.metadata as m,json; print(json.dumps({d.metadata["Name"]:d.version for d in m.distributions()},sort_keys=True))'
a=subprocess.check_output(['docker','run','--rm','--network','none','--entrypoint','python',b['rollback_image'],'-c',probe])
z=subprocess.check_output(['docker','run','--rm','--network','none','--entrypoint','python','edgepulse:paper','-c',probe])
assert json.loads(a)==json.loads(z),'dependency drift'
f=backup/'test_paper_growth.py';f.write_bytes(base64.b64decode(''));f.chmod(0o644)
r=subprocess.run(['docker','run','--rm','--network','none','--read-only','--tmpfs','/tmp:mode=1777','--mount','type=bind,source='+str(f)+',target=/tmp/test_paper_growth.py,readonly','--entrypoint','python','edgepulse:paper','/tmp/test_paper_growth.py'],text=True,capture_output=True)
(backup/'container-tests.log').write_text(r.stdout+r.stderr)
print('source upload and image build complete; original dependencies unchanged')
print(r.stdout+r.stderr)
assert r.returncode==0,'container tests failed'
